function cdqVersionDetailV87(v){
  v=String(v||'').trim();
  return v||'—';
}
function cdqCompareVersionV2248(a,b){
  function parts(v){
    const m=String(v||'').match(/v(\d+)\.(\d+)(?:\.(\d+))?/i);
    return m?[Number(m[1]||0),Number(m[2]||0),Number(m[3]||0)]:[0,0,0];
  }
  const A=parts(a),B=parts(b);
  for(let i=0;i<3;i++){if(A[i]!==B[i])return A[i]-B[i];}
  return 0;
}

